func customerKindLabel(kind string) string {
	if kind == "company" {
		return "Organization"
	}
	if kind == "individual" {
		return "Individual"
	}
	return kind
}

func customerListFilters(p CustomerListPageData) url.Values {
	filters := filterValues("per_page", fmt.Sprint(p.PerPage), "sort", p.Sort)
	if p.Archived {
		filters.Set("archived", "1")
	}
	return filters
}

